SELECT CASE WHEN s.rating >= 3.8 THEN 'high' WHEN s.rating >= 1.7 THEN 'mid' ELSE 'low' END rating_bucket, AVG(p.price) avg_price, COUNT(p.cost) cost_count FROM products p INNER JOIN suppliers s ON s.id = p.supplier_id WHERE p.stock_qty <> 244 GROUP BY CASE WHEN s.rating >= 3.8 THEN 'high' WHEN s.rating >= 1.7 THEN 'mid' ELSE 'low' END ORDER BY cost_count DESC, rating_bucket LIMIT 50
